-- Schema for the first live loop: a Telegram order becomes picking work on
-- the glasses, and progress goes back to the chat.
--
-- Tenancy is enforced by the database, not only by queries: every child row
-- carries workspace_id and references its parent through (workspace_id, id),
-- so a row can never point at another workspace's data.
--
-- IDs are UUIDv7 generated by Postgres. Quantities are integers. Versions and
-- sequences are bigint and travel as decimal strings on the wire.

create table workspaces (
  id uuid primary key default uuidv7(),
  name text not null check (length(name) between 1 and 80),
  timezone text not null default 'UTC',
  event_seq bigint not null default 0 check (event_seq >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table members (
  workspace_id uuid not null references workspaces (id),
  id uuid not null default uuidv7(),
  display_name text not null check (length(display_name) between 1 and 80),
  role text not null check (role in ('OWNER', 'COORDINATOR', 'PICKER', 'VIEWER')),
  telegram_user_id text check (telegram_user_id ~ '^[0-9]{1,20}$'),
  created_at timestamptz not null default now(),
  primary key (id),
  unique (workspace_id, id),
  unique (workspace_id, telegram_user_id)
);

create table products (
  workspace_id uuid not null references workspaces (id),
  id uuid not null default uuidv7(),
  sku text not null check (length(sku) between 1 and 64),
  normalized_sku text not null check (length(normalized_sku) between 1 and 64),
  name text not null check (length(name) between 1 and 120),
  bin text check (length(bin) between 1 and 32),
  route_rank integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id),
  unique (workspace_id, id),
  unique (workspace_id, normalized_sku)
);

create table orders (
  workspace_id uuid not null references workspaces (id),
  id uuid not null default uuidv7(),
  ref text not null check (length(ref) between 1 and 40),
  source_key text check (length(source_key) <= 200),
  created_by uuid not null,
  revision integer not null default 1 check (revision >= 1),
  version bigint not null default 1 check (version >= 1),
  terminal text check (terminal in ('COMPLETED', 'CANCELLED')),
  is_paused boolean not null default false,
  is_cancel_requested boolean not null default false,
  is_release_requested boolean not null default false,
  priority integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id),
  unique (workspace_id, id),
  unique (workspace_id, ref),
  unique (workspace_id, source_key),
  foreign key (workspace_id, created_by) references members (workspace_id, id)
);
create index orders_queue on orders (workspace_id, priority desc, created_at) where terminal is null;

create table order_lines (
  workspace_id uuid not null,
  id uuid not null default uuidv7(),
  order_id uuid not null,
  product_id uuid not null,
  sku_snapshot text not null,
  name_snapshot text not null,
  bin_snapshot text,
  route_rank_snapshot integer not null,
  creation_index integer not null check (creation_index >= 0),
  requested_qty integer not null check (requested_qty between 0 and 10000),
  picked_qty integer not null default 0 check (picked_qty >= 0),
  primary key (id),
  unique (workspace_id, id),
  unique (order_id, sku_snapshot),
  foreign key (workspace_id, order_id) references orders (workspace_id, id),
  foreign key (workspace_id, product_id) references products (workspace_id, id)
);
create index order_lines_product on order_lines (workspace_id, product_id);

create table assignments (
  workspace_id uuid not null,
  id uuid not null default uuidv7(),
  order_id uuid not null,
  worker_id uuid not null,
  tote_id text check (length(tote_id) between 1 and 16),
  is_accepted boolean not null default false,
  ack_revision integer not null check (ack_revision >= 0),
  created_at timestamptz not null default now(),
  released_at timestamptz,
  primary key (id),
  foreign key (workspace_id, order_id) references orders (workspace_id, id),
  foreign key (workspace_id, worker_id) references members (workspace_id, id)
);
-- At most one live assignment per order.
create unique index assignments_one_active on assignments (order_id) where released_at is null;
create index assignments_worker on assignments (workspace_id, worker_id) where released_at is null;

-- Glasses authenticate with an opaque token; only its SHA-256 is stored.
create table device_tokens (
  workspace_id uuid not null,
  id uuid not null default uuidv7(),
  member_id uuid not null,
  label text not null check (length(label) between 1 and 60),
  token_hash text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  expires_at timestamptz not null,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  primary key (id),
  foreign key (workspace_id, member_id) references members (workspace_id, id)
);

-- Append-only history. seq is allocated from workspaces.event_seq inside the
-- same transaction as the change it records.
create table fulfilment_events (
  workspace_id uuid not null references workspaces (id),
  seq bigint not null check (seq >= 1),
  id uuid not null default uuidv7(),
  order_id uuid,
  event_type text not null check (event_type ~ '^[A-Z_]{3,40}$'),
  actor_member_id uuid,
  command_id uuid,
  revision integer,
  version bigint,
  payload jsonb not null default '{}',
  occurred_at timestamptz not null default now(),
  primary key (id),
  unique (workspace_id, seq),
  foreign key (workspace_id, order_id) references orders (workspace_id, id),
  foreign key (workspace_id, actor_member_id) references members (workspace_id, id)
);
create index fulfilment_events_order on fulfilment_events (order_id, seq);

-- The first result of each command, so a retry with the same ID returns it
-- instead of applying the command twice.
create table command_results (
  workspace_id uuid not null,
  actor_member_id uuid not null,
  command_id uuid not null,
  request_hash text not null check (request_hash ~ '^[0-9a-f]{64}$'),
  http_status integer not null,
  response jsonb not null,
  created_at timestamptz not null default now(),
  primary key (workspace_id, actor_member_id, command_id),
  foreign key (workspace_id, actor_member_id) references members (workspace_id, id)
);

create table telegram_connections (
  workspace_id uuid not null references workspaces (id),
  id uuid not null default uuidv7(),
  chat_id text not null check (chat_id ~ '^-?[0-9]{1,20}$'),
  status text not null check (status in ('ACTIVE', 'DISCONNECTED')),
  bound_by uuid not null,
  created_at timestamptz not null default now(),
  primary key (id),
  unique (workspace_id, id),
  foreign key (workspace_id, bound_by) references members (workspace_id, id)
);
-- A chat drives exactly one workspace at a time.
create unique index telegram_connections_one_active on telegram_connections (chat_id) where status = 'ACTIVE';

-- Every update is stored before it is processed, deduplicated by update_id.
create table telegram_inbox (
  bot_alias text not null,
  update_id text not null check (update_id ~ '^[0-9]{1,20}$'),
  id uuid not null default uuidv7(),
  status text not null default 'PENDING' check (status in ('PENDING', 'DONE', 'FAILED', 'IGNORED')),
  payload jsonb not null,
  attempts integer not null default 0 check (attempts between 0 and 10),
  next_attempt_at timestamptz not null default now(),
  error_code text,
  received_at timestamptz not null default now(),
  primary key (id),
  unique (bot_alias, update_id)
);
create index telegram_inbox_pending on telegram_inbox (next_attempt_at) where status = 'PENDING';

-- Messages to send, written in the same transaction as the change they report.
create table telegram_outbox (
  workspace_id uuid not null,
  id uuid not null default uuidv7(),
  connection_id uuid not null,
  order_id uuid,
  kind text not null check (kind in ('STATUS', 'REPLY')),
  dedupe_key text not null check (length(dedupe_key) <= 200),
  payload jsonb not null,
  status text not null default 'PENDING' check (status in ('PENDING', 'SENDING', 'SENT', 'RETRY', 'FAILED', 'UNCERTAIN', 'CANCELLED')),
  attempts integer not null default 0 check (attempts between 0 and 8),
  next_attempt_at timestamptz not null default now(),
  lease_until timestamptz,
  provider_message_id text,
  last_error_code text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (id),
  unique (workspace_id, dedupe_key),
  foreign key (workspace_id, connection_id) references telegram_connections (workspace_id, id),
  foreign key (workspace_id, order_id) references orders (workspace_id, id)
);
create index telegram_outbox_due on telegram_outbox (next_attempt_at) where status in ('PENDING', 'RETRY');

-- The bot-owned status message for each order, edited in place as work moves.
create table telegram_message_refs (
  workspace_id uuid not null,
  connection_id uuid not null,
  order_id uuid not null,
  purpose text not null check (purpose in ('STATUS')),
  message_id text not null check (message_id ~ '^[0-9]{1,20}$'),
  last_rendered_version bigint not null,
  primary key (connection_id, order_id, purpose),
  foreign key (workspace_id, connection_id) references telegram_connections (workspace_id, id),
  foreign key (workspace_id, order_id) references orders (workspace_id, id)
);
